import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))
    x = int(next(iterator))
    y = int(next(iterator))

    a = []
    for _ in range(n):
        a.append(int(next(iterator)))

    for i in range(n):
        is_valid = True
        # Check x days before
        start_before = max(0, i - x)
        for j in range(start_before, i):
            if a[j] <= a[i]:
                is_valid = False
                break
        if not is_valid:
            continue

        # Check y days after
        end_after = min(n, i + y + 1)
        for j in range(i + 1, end_after):
            if a[j] <= a[i]:
                is_valid = False
                break
        if is_valid:
            print(i + 1)
            return

if __name__ == "__main__":
    solve()
